(function(){
const area=document.querySelector('#admin-panel');if(!area)return;area.insertAdjacentHTML('beforeend','<section id="admin-customers" class="admin-orders" hidden><h2>Clientes cadastrados</h2><div id="admin-customer-list"></div></section>');
const dateValue=value=>value?new Date(value+'T00:00:00').toLocaleDateString('pt-BR'):'Não informado';
const addressValue=address=>{if(!address||typeof address!=='object')return 'Não informado';const values=[address.street,address.number,address.neighborhood,address.reference?'Referência: '+address.reference:''].filter(Boolean);return values.length?values.join(', '):'Não informado'};
async function loadCustomers(){const list=document.querySelector('#admin-customer-list');try{const rows=await request('/rest/v1/profiles?select=id,full_name,email,phone,birth_date,cpf,default_address,created_at&role=eq.customer&order=created_at.desc');list.innerHTML=rows.length?rows.map(c=>`<details class="admin-customer-card"><summary><strong>${escapeHtml(c.full_name||'Cliente sem nome')}</strong><span>${escapeHtml(c.email||'E-mail não informado')}</span></summary><div class="admin-customer-data"><p><b>Nome completo:</b> ${escapeHtml(c.full_name||'Não informado')}</p><p><b>E-mail:</b> ${escapeHtml(c.email||'Não informado')}</p><p><b>Data de nascimento:</b> ${escapeHtml(dateValue(c.birth_date))}</p><p><b>CPF:</b> ${escapeHtml(c.cpf||'Não informado')}</p><p><b>Telefone:</b> ${escapeHtml(c.phone||'Não informado')}</p><p><b>Endereço:</b> ${escapeHtml(addressValue(c.default_address))}</p><p class="muted"><b>Cadastro:</b> ${escapeHtml(new Date(c.created_at).toLocaleDateString('pt-BR'))}</p></div></details>`).join(''):'<p>Nenhum cliente cadastrado.</p>'}catch(e){list.innerHTML='<p>'+escapeHtml(e.message)+'</p>'}}
window.loadAdminCustomers=loadCustomers;
})();

